// Minimal stand-in for the desktop app's plugin SDK, mirroring the real
// signatures the follow-up plugin uses (see apps/desktop/src/sdk/index.ts).
import { createElement } from 'react'

export const cn = (...parts) => parts.filter(Boolean).join(' ')

export const haptic = () => {}

export const Codicon = ({ name, className }) =>
  createElement('i', { 'aria-hidden': 'true', className: `codicon codicon-${name} ${className || ''}`.trim() })

// Real Tip renders children as the trigger (asChild) and the label as tooltip
// content shown on hover — for assertions the trigger is what matters.
export const Tip = ({ label, children }) => (label ? children : children)

export const usePluginI18n = () => key => key

export const host = {
  notify: () => {},
  state: {}
}
